import assert from 'node:assert/strict';

export async function runMotionLayersSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY)}));
  async function frame(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.im-hov[data-motion-canvas]'));return (await page.$('.nw-motion-dialog iframe')).contentFrame();}
  async function layers(){return page.$$eval('[data-motion-layer]',ns=>ns.map(n=>({id:n.dataset.motionLayer,name:n.querySelector('strong').textContent,type:n.querySelector('small').textContent,pressed:n.getAttribute('aria-pressed')})));}
  async function selected(id){assert.deepEqual(await page.$$eval('[data-motion-layer][aria-pressed="true"]',ns=>ns.map(n=>n.dataset.motionLayer)),[id]);assert.equal(await page.evaluate(id=>document.querySelector('.nw-motion-dialog iframe').contentDocument.querySelector('[data-id="'+id+'"]')?.classList.contains('nw-motion-selected'),id),true);}
  async function choose(id){await page.click('[data-motion-layer="'+id+'"]');await selected(id);}
  await page.click('.tb-left [data-motion-open]');await frame();assert.equal(await page.$eval('[data-motion-library-page="elements"]',n=>n.hidden),true);assert.equal((await layers()).length,6);
  await page.click('[data-motion-template="card-tunnel"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Una nueva perspectiva.');const items=await layers();assert.equal(items.filter(e=>e.type==='Imagen').length,3);assert.equal(items.filter(e=>e.type==='Texto').length,3);
  const f=await frame(),heading=await f.$('.hd'),headingId=await heading.evaluate(n=>n.dataset.id);assert.equal(items[4].id,headingId,'List order follows composition elements');
  await page.$eval('[data-motion-progress]',n=>{n.value='0';n.dispatchEvent(new Event('input',{bubbles:true}));});const hidden=await f.$eval('.im-hov',n=>({id:n.dataset.id,opacity:+getComputedStyle(n).opacity,pointer:getComputedStyle(n).pointerEvents}));assert.equal(hidden.opacity,0);assert.equal(hidden.pointer,'none');
  await page.click('[data-motion-library-tab="elements"]');await choose(hidden.id);assert.equal(await page.$eval('[data-motion-key-panel]',n=>n.hidden),false);assert.equal(await page.$eval('[data-motion-play]',n=>n.getAttribute('aria-pressed')),'false');assert.equal(await page.$eval('[data-motion-progress]',n=>n.value),'0','Selecting an invisible layer preserves the current moment');
  await page.$eval('[data-motion-key-property="z"]',n=>{n.value='-650';n.dispatchEvent(new Event('change',{bubbles:true}));});assert.equal(await f.$eval('[data-id="'+hidden.id+'"]',n=>n.style.getPropertyValue('--nw-sd-z')),'-650.00px');
  const r=await heading.boundingBox();await page.mouse.click(r.x+r.width/2,r.y+r.height/2);await selected(headingId);assert.equal(await page.$eval('[data-motion-text-style-panel]',n=>n.hidden),false,'Canvas selection updates the list and inspector');
  await heading.focus();await page.keyboard.press('Enter');await page.keyboard.type('Título desde capas');const third=await page.$('[data-motion-layer="'+items[2].id+'"]');await third.focus();await page.keyboard.press('Enter');await selected(items[2].id);assert.equal(await page.$eval('[data-motion-content="4"]',n=>n.value),'Título desde capas','Layer selection confirms pending direct text editing');
  const tab=await page.$('[data-motion-library-tab="elements"]');await tab.focus();await page.keyboard.press('Home');assert.equal(await page.$eval('[data-motion-library-tab="library"]',n=>n.getAttribute('aria-selected')),'true');await page.keyboard.press('End');assert.equal(await page.$eval('[data-motion-library-tab="elements"]',n=>n.getAttribute('aria-selected')),'true');
  await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');assert.ok(!(await layers()).some(l=>items.some(old=>old.id===l.id)),'Changing templates replaces the element list');await page.click('[data-motion-template="card-tunnel"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Título desde capas');assert.deepEqual((await layers()).map(l=>l.id),items.map(l=>l.id));await selected(items[2].id);
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(({id,headingId})=>({project:JSON.stringify(project),group:sec().elements.find(e=>e.nwMotionInstance),image:sec().elements.find(e=>e.id===id),heading:sec().elements.find(e=>e.id===headingId)}),{id:hidden.id,headingId});assert.equal(inserted.image.sdKeyframes[0].z,-650);assert.equal(inserted.heading.text,'Título desde capas');await page.waitForFunction(()=>document.querySelector('[data-motion-layers]').childElementCount===0);assert.equal(await page.$eval('[data-motion-library-tab="library"]',n=>n.getAttribute('aria-selected')),'true');
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await frame();await page.click('[data-motion-library-tab="elements"]');assert.deepEqual((await layers()).map(l=>l.id),items.map(l=>l.id));assert.equal(await page.$$eval('[data-motion-layer]',ns=>ns.every(n=>!n.disabled)),true,'Elements remain available while template choices are disabled');await choose(headingId);await page.$eval('[data-motion-content="4"]',n=>{n.value='Título guardado';n.dispatchEvent(new Event('change',{bubbles:true}));});await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected')?.textContent==='Título guardado',{},headingId);await selected(headingId);await page.click('[data-motion-save]');const saved=await page.evaluate(id=>({project:JSON.stringify(project),text:sec().elements.find(e=>e.id===id).text,groups:sec().elements.filter(e=>e.nwMotionInstance).length}),headingId);assert.equal(saved.text,'Título guardado');assert.equal(saved.groups,1);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);await frame();await page.click('[data-motion-library-tab="elements"]');await choose(hidden.id);await page.$eval('[data-motion-width]',n=>{n.value='40';n.dispatchEvent(new Event('change',{bubbles:true}));});await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await frame();await page.click('[data-motion-library-tab="elements"]');const mobile=await layers();await choose(mobile[5].id);assert.ok(await page.evaluate(()=>{const d=document.querySelector('.nw-motion-dialog'),lib=d.querySelector('.nw-motion-library'),s=d.querySelector('.nw-motion-stage'),a=lib.getBoundingClientRect(),b=s.getBoundingClientRect();return d.scrollWidth<=d.clientWidth+2&&a.bottom<=b.top+1&&lib.scrollWidth>lib.clientWidth;}),'Compact layout keeps layers in a horizontal scrolling row');assert.equal(await page.$eval('[data-motion-text-style-panel]',n=>n.hidden),false);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  console.log('Elementos Motion Lab: selección de lámina invisible/superpuesta, sincronización lienzo/panel/lista, texto directo y teclado, tabs accesibles, borradores sin escritura, insertar/reabrir/guardar/cancelar, historial y pantalla compacta OK');
 }finally{
  await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
